"""Interview problems 4-27 (probability + expected value). Every number is checked below."""
import math
from fractions import Fraction as Fr
from iq_helpers import *

# ---- verification of the numbers used in the narration -------------------------------------------------------------
assert abs(birthday_p(23) - 0.5073) < 1e-3
assert abs(1 - (5 / 6) ** 4 - 0.5177) < 1e-3 and abs(1 - (35 / 36) ** 24 - 0.4914) < 1e-3
assert abs(sum(6 / k for k in range(1, 7)) - 14.7) < 1e-9
assert abs(1 / math.e - 0.3679) < 1e-4
assert abs(6 / math.pi ** 2 - 0.6079) < 1e-4
E_HH = Fr(6)      # solved below by hand: E_S = 1 + E_A/2 + E_S/2 ; E_A = 1 + E_S/2
assert 1 + Fr(1, 2) * (1 + Fr(1, 2) * E_HH) + Fr(1, 2) * E_HH == E_HH
assert Fr(2) == 1 + Fr(1, 2) * Fr(2) + Fr(1, 2) * 0 and Fr(4) == 1 + Fr(1, 2) * Fr(2) + Fr(1, 2) * Fr(4)
E0 = Fr(42)
assert E0 == 1 + Fr(1, 6) * (1 + Fr(5, 6) * E0) + Fr(5, 6) * E0
bp = {n: birthday_p(n) for n in (10, 20, 23, 30, 40, 50, 57)}


def sec_prob(n, k):
    return (k / n) * sum(1 / i for i in range(k, n))


